function status(date){if(!date)return'missing';const days=Math.ceil((new Date(`${date}T23:59:59`)-new Date())/86400000);if(days<0)return'expired';if(days<=15)return'urgent';return'ok'}
const statusLabel=s=>({expired:'Vencida',urgent:'Urgente',ok:'Regular',missing:'Pendente'}[s]);
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function setBusy(button,busy,label='Salvando...'){if(!button)return;button.disabled=busy;if(busy){button.dataset.original=button.textContent;button.textContent=label}else button.textContent=button.dataset.original||button.textContent}
function showAuthMessage(message,success=false){const el=$('#auth-message');el.textContent=message;el.style.color=success?'var(--green)':'var(--red)'}
function friendlyError(error){const msg=error?.message||String(error);if(/Invalid login credentials/i.test(msg))return'E-mail ou senha incorretos.';if(/Email not confirmed/i.test(msg))return'Confirme seu e-mail antes de entrar.';if(/already registered/i.test(msg))return'Este e-mail já está cadastrado.';return msg}
function safeName(name){return name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9._-]/g,'_').slice(-120)}
function safeFolder(name){return String(name||'outros').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'outros'}
function cnpjDigits(value){return String(value||'').replace(/\D/g,'').slice(0,14)}
function formatCnpj(value){const v=cnpjDigits(value);return v.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d)/,'$1-$2')}
function validCnpj(value){const v=cnpjDigits(value);if(v.length!==14||/^(\d)\1{13}$/.test(v))return false;const digit=base=>{let sum=0,weight=base.length-7;for(const n of base){sum+=Number(n)*weight--;if(weight<2)weight=9}const mod=sum%11;return mod<2?0:11-mod};return digit(v.slice(0,12))===Number(v[12])&&digit(v.slice(0,13))===Number(v[13])}
async function searchCnpj(){const input=$('#modal-content [name="cnpj"]'),button=$('#search-cnpj'),message=$('#cnpj-message'),cnpj=cnpjDigits(input?.value);if(!validCnpj(cnpj)){message.textContent='Informe um CNPJ válido com 14 dígitos.';message.className='field-message error';return}setBusy(button,true,'Consultando...');message.textContent='Consultando cadastro público...';message.className='field-message';let timer;try{const controller=new AbortController();timer=setTimeout(()=>controller.abort(),10000);const response=await fetch(`https://brasilapi.com.br/api/cnpj/v1/${cnpj}`,{signal:controller.signal,headers:{Accept:'application/json'}});if(response.status===404)throw new Error('CNPJ não localizado na base consultada.');if(!response.ok)throw new Error('A consulta pública está temporariamente indisponível.');const data=await response.json(),activities=[data.cnae_fiscal_descricao,...(data.cnaes_secundarios||[]).map(x=>x.descricao)].filter(Boolean);const values={name:data.razao_social,trade:data.nome_fantasia,city:data.municipio,state:data.uf,openingDate:data.data_inicio_atividade,legalNature:data.natureza_juridica,size:data.descricao_porte||data.porte,activities:[...new Set(activities)].slice(0,15).join('; ')};Object.entries(values).forEach(([name,value])=>{const field=$(`#modal-content [name="${name}"]`);if(field&&value)field.value=value});input.value=formatCnpj(cnpj);message.textContent='Dados encontrados. Confira antes de salvar.';message.className='field-message success'}catch(error){message.textContent=error.name==='AbortError'?'A consulta demorou demais. Tente novamente ou preencha manualmente.':friendlyError(error);message.className='field-message error'}finally{clearTimeout(timer);setBusy(button,false)}}

async function init(){if(!client){showAuthMessage('Configuração do Supabase não encontrada.');return}const {data}=await client.auth.getSession();if(data.session)await enterApp(data.session.user);client.auth.onAuthStateChange(async(event,session)=>{if(event==='SIGNED_OUT')showLogin();else if(session&&!state.user)await enterApp(session.user)})}
async function enterApp(user){state.user=user;const {data:profile,error}=await client.from('perfis').select('*').eq('id',user.id).single();if(error){showAuthMessage('Execute primeiro o arquivo supabase/schema.sql no SQL Editor.');showLogin();return}state.profile={id:profile.id,email:profile.email,name:profile.nome,role:profile.perfil,companyId:profile.empresa_id};if(profile.perfil==='pendente'){$('#auth-screen').hidden=true;$('#pending-screen').hidden=false;document.body.classList.remove('authenticated');return}$('#auth-screen').hidden=true;$('#pending-screen').hidden=true;document.body.classList.add('authenticated');$('#user-label').textContent=profile.nome||profile.email;$('#access-nav').hidden=!isAdmin();$$('[data-open="company"]').forEach(b=>b.hidden=!isAdmin());await loadData();navigate('dashboard')}
function showLogin(){state={user:null,profile:null,companies:[],documents:[],certificates:[],balances:[],notices:[],packages:[],profiles:[],checklist:[],agenda:[]};document.body.classList.remove('authenticated');$('#pending-screen').hidden=true;$('#auth-screen').hidden=false}
async function loadData(){const requests=[client.from('empresas').select('*').order('razao_social'),client.from('certidoes').select('*').order('validade'),client.from('balancos').select('*').order('exercicio',{ascending:false}),client.from('licitacoes').select('*').order('abertura'),client.from('pacotes').select('*').order('criado_em',{ascending:false}),client.from('documentos_empresa').select('*').order('criado_em',{ascending:false}),client.from('licitacao_checklist_itens').select('*').order('ordem'),client.from('agenda_tarefas').select('*').order('prazo'),client.from('parametros_legais').select('*')];if(isAdmin())requests.push(client.from('perfis').select('*').order('email'));const results=await Promise.all(requests),failure=[results[0],results[1],results[3],results[9]].find(r=>r?.error);if(failure){toast(friendlyError(failure.error));return}if(results[6]?.error||results[7]?.error)toast('Execute supabase/atualizacao_wizard_licitacoes.sql para habilitar o assistente e a agenda.');state.companies=results[0].data.map(x=>({id:x.id,name:x.razao_social,trade:x.nome_fantasia,cnpj:x.cnpj,city:x.municipio,state:x.uf,activities:x.atividades,openingDate:x.data_abertura,legalNature:x.natureza_juridica,size:x.porte}));state.certificates=results[1].data.map(x=>({id:x.id,companyId:x.empresa_id,type:x.tipo,issuer:x.orgao_emissor,issued:x.emissao,validity:x.validade,link:x.link_emissao,filePath:x.arquivo_path}));state.balances=(results[2].data||[]).map(x=>({id:x.id,companyId:x.empresa_id,year:x.exercicio,documentType:x.tipo_documento,periodStart:x.periodo_inicio,periodEnd:x.periodo_fim,registrationDate:x.data_registro,registrationOffice:x.orgao_registro,filePath:x.arquivo_path,notes:x.observacoes}));state.notices=results[3].data.map(x=>({id:x.id,companyId:x.empresa_id,number:x.numero,agency:x.orgao,object:x.objeto,opening:x.abertura,horaSessao:x.hora_sessao,modality:x.modalidade,linkPortal:x.link_portal,requirements:x.requisitos||[],proposalRequirements:x.requisitos_proposta||[],declarations:x.declaracoes||[],items:x.itens||[],filePath:x.edital_path,extractedText:x.texto_extraido,temCertame:x.tem_certame!==false,modalidadePadrao:x.modalidade_padrao,formaDireta:x.forma_contratacao_direta,fundamentoLegal:x.fundamento_legal,tipoObjeto:x.tipo_objeto,criterio:x.criterio_julgamento,modoDisputa:x.modo_disputa,regime:x.regime_execucao,meEpp:x.exclusividade_me_epp||'nao',valorEstimado:x.valor_estimado,procedimentoAuxiliar:x.procedimento_auxiliar,statusProcesso:x.status_processo||'rascunho',interesse:x.interesse||'em_analise',prioridade:x.prioridade||'media',responsavel:x.responsavel,anotacoes:x.anotacoes,decidirAte:x.decidir_ate}));state.packages=(results[4].data||[]).map(x=>({id:x.id,companyId:x.empresa_id,noticeId:x.licitacao_id,name:x.nome,status:x.status,documents:x.documentos||[],proposal:x.proposta||{},declarations:x.declaracoes||[],items:x.itens||[],createdAt:x.criado_em}));state.documents=(results[5]?.data||[]).map(x=>({id:x.id,companyId:x.empresa_id,category:x.categoria,type:x.tipo,name:x.nome_original,filePath:x.arquivo_path,source:x.origem,sourceFolder:x.pasta_origem,documentDate:x.data_documento,validity:x.validade,hash:x.sha256,metadata:x.metadados||{},createdAt:x.criado_em}));state.profiles=(results[9]?.data||[]).map(x=>({id:x.id,email:x.email,name:x.nome,role:x.perfil,companyId:x.empresa_id}));state.checklist=(results[6]?.data||[]).map(x=>({id:x.id,companyId:x.empresa_id,noticeId:x.licitacao_id,chave:x.chave,bloco:x.bloco,titulo:x.titulo,baseLegal:x.base_legal,ordem:x.ordem,obrigatorio:x.obrigatorio,aplicavel:x.aplicavel,justificativa:x.justificativa_nao_aplicavel,documentoRefTabela:x.documento_ref_tabela,documentoRefId:x.documento_ref_id,documentoRefPath:x.documento_ref_path,validade:x.validade,status:x.status,observacao:x.observacao}));state.agenda=(results[7]?.data||[]).map(x=>({id:x.id,companyId:x.empresa_id,noticeId:x.licitacao_id,checklistItemId:x.checklist_item_id,titulo:x.titulo,detalhe:x.detalhe,prazo:x.prazo,responsavel:x.responsavel,origem:x.origem,concluida:x.concluida,concluidaEm:x.concluida_em}));if(results[8]?.data?.length)Regras.definirParametros(Object.fromEntries(results[8].data.map(x=>[x.chave,Number(x.valor)])));renderAll()}
function navigate(view){$$('.view').forEach(v=>v.classList.toggle('active',v.id===view));$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-title').textContent=({dashboard:'Visão geral',companies:'Empresas',archive:'Acervo documental',certificates:'Certidões',balances:'Balanços patrimoniais',notices:'Editais',agenda:'Agenda de interesse',packages:'Pacotes de participação',access:'Acessos'})[view]}
function renderMetrics(){const expired=state.certificates.filter(c=>status(c.validity)==='expired').length,urgent=state.certificates.filter(c=>status(c.validity)==='urgent').length;const hoje=new Date().toISOString().slice(0,10),tarefas=state.agenda.filter(t=>!t.concluida),atrasadas=tarefas.filter(t=>t.prazo&&t.prazo<hoje).length,participar=state.notices.filter(n=>n.interesse==='vamos_participar'&&(!n.opening||n.opening>=hoje)).length;$('#metrics').innerHTML=`<div class="metric"><span>Empresas</span><strong>${state.companies.length}</strong><small>Disponíveis para você</small></div><div class="metric red"><span>Certidões vencidas</span><strong>${expired}</strong><small>Exigem providência</small></div><div class="metric amber"><span>Vencem em até 15 dias</span><strong>${urgent}</strong><small>Atenção imediata</small></div><div class="metric${atrasadas?' red':''}"><span>Vamos participar</span><strong>${participar}</strong><small>${tarefas.length} providência(s), ${atrasadas} atrasada(s)</small></div>`}
function renderAlerts(){const items=[...state.certificates].sort((a,b)=>(a.validity||'9999').localeCompare(b.validity||'9999')).slice(0,6);$('#alerts').innerHTML=items.length?items.map(c=>`<div class="list-row"><p><strong>${esc(c.type)}</strong><br><small>${esc(companyName(c.companyId))} · ${fmt(c.validity)}</small></p><span class="badge ${status(c.validity)}">${statusLabel(status(c.validity))}</span></div>`).join(''):'<div class="empty">Nenhuma certidão cadastrada.</div>'}
function renderUpcoming(){const items=[...state.notices].filter(n=>!n.opening||new Date(`${n.opening}T23:59:59`)>=new Date()).sort((a,b)=>(a.opening||'9999').localeCompare(b.opening||'9999')).slice(0,5);$('#upcoming').innerHTML=items.length?items.map(n=>{const itens=state.checklist.filter(c=>c.noticeId===n.id&&c.aplicavel!==false),r=window.Regras?Regras.contar(itens):{criticos:0,total:0};return`<div class="list-row"><p><strong>${esc(n.number)}</strong><br><small>${esc(n.agency)} · ${r.total?`${r.prontos}/${r.total} documentos prontos`:'checklist ainda não calculado'}</small></p><span>${fmt(n.opening)}${r.criticos?`<br><small class="pend">${r.criticos} pendência(s)</small>`:''}</span></div>`}).join(''):'<div class="empty">Nenhuma licitação futura cadastrada.</div>'}
function renderCompanies(){const q=$('#company-search')?.value.toLowerCase()||'';const list=state.companies.filter(c=>(c.name+c.cnpj).toLowerCase().includes(q));$('#company-list').innerHTML=list.length?list.map(c=>{const certs=state.certificates.filter(x=>x.companyId===c.id),bad=certs.filter(x=>status(x.validity)!=='ok').length;return`<article class="card company-card"><h3>${esc(c.name)}</h3><div class="meta">${esc(c.trade||'Sem nome fantasia')} · ${esc(c.cnpj)}</div><p>${esc(c.city||'Município não informado')} ${c.state?'— '+esc(c.state):''}</p><div class="stats"><span><strong>${certs.length}</strong>certidões</span><span><strong>${bad}</strong>pendências</span></div></article>`}).join(''):'<div class="empty">Nenhuma empresa encontrada.</div>';renderSelects()}
const archiveCategories=['Certidões','Balanços','Societários','Atestados técnicos','Licenças e alvarás','Representação','Declarações','Propostas','Editais e processos','Identificação','Dados bancários','Outros'];
function renderArchive(){const root=$('#archive-list'),filter=$('#archive-filter')?.value||'all',categories=[...new Set([...archiveCategories,...state.documents.map(d=>d.category).filter(Boolean)])].sort((a,b)=>a.localeCompare(b,'pt-BR'));if($('#archive-filter')){const selected=$('#archive-filter').value;$('#archive-filter').innerHTML='<option value="all">Todas as categorias</option>'+categories.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}const list=state.documents.filter(d=>filter==='all'||d.category===filter).sort((a,b)=>companyName(a.companyId).localeCompare(companyName(b.companyId),'pt-BR')||a.category.localeCompare(b.category,'pt-BR')||(b.documentDate||b.createdAt||'').localeCompare(a.documentDate||a.createdAt||''));if($('#archive-count'))$('#archive-count').textContent=`${list.length} documento(s)`;if(root)root.innerHTML=list.length?list.map(d=>`<tr><td>${esc(companyName(d.companyId))}</td><td><span class="badge ok">${esc(d.category)}</span></td><td><strong>${esc(d.type||d.name)}</strong><br><small>${esc(d.name)}</small></td><td>${fmt(d.documentDate)}</td><td>${fmt(d.validity)}</td><td>${esc(d.source||'LiciDoc')}${d.sourceFolder?`<br><small>${esc(d.sourceFolder)}</small>`:''}</td><td><button class="link" data-document="${esc(d.filePath)}">Abrir</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">Nenhum documento arquivado nesta categoria.</td></tr>'}
function renderCertificates(){const filter=$('#certificate-filter')?.value||'all',all=[...state.certificates].sort((a,b)=>companyName(a.companyId).localeCompare(companyName(b.companyId),'pt-BR')||a.type.localeCompare(b.type,'pt-BR')||(b.validity||'').localeCompare(a.validity||'')),list=all.filter(c=>filter==='all'||status(c.validity)===filter),latest=new Set();all.forEach(c=>{const key=`${c.companyId}:${c.type}`;if(!latest.has(key))latest.add(key),c.isLatest=true;else c.isLatest=false});$('#certificate-list').innerHTML=list.length?list.map(c=>`<tr><td>${esc(companyName(c.companyId))}</td><td><strong>${esc(c.type)}</strong><br><small>${c.isLatest?'Versão atual':'Histórico preservado'}</small></td><td>${esc(c.issuer||'—')}</td><td>${fmt(c.validity)}</td><td><span class="badge ${status(c.validity)}">${statusLabel(status(c.validity))}</span></td><td>${c.filePath?`<button class="link" data-document="${esc(c.filePath)}">Abrir PDF</button> · `:''}${c.link?`<a href="${esc(c.link)}" target="_blank" rel="noopener">Emitir nova ↗</a>`:'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhuma certidão nessa situação.</td></tr>'}
const STATUS_PROCESSO={rascunho:'Rascunho',em_conferencia:'Em conferência',pronto:'Pronto',enviado:'Enviado',arquivado:'Arquivado'};
function classificacaoLabel(n){if(!window.Regras)return n.modality||'';const partes=[];if(n.temCertame===false)partes.push(Regras.rotulo(Regras.formasDiretas,n.formaDireta)||'Contratação direta');else if(n.modalidadePadrao)partes.push(Regras.rotulo(Regras.modalidades,n.modalidadePadrao));if(n.fundamentoLegal)partes.push(n.fundamentoLegal);if(n.tipoObjeto)partes.push(Regras.rotulo(Regras.tiposObjeto,n.tipoObjeto));if(n.valorEstimado)partes.push(Regras.moeda(n.valorEstimado));return partes.join(' · ')||n.modality||'Classificação pendente'}
function renderNotices(){$('#notice-list').innerHTML=state.notices.length?state.notices.map(n=>{const itens=state.checklist.filter(c=>c.noticeId===n.id&&c.aplicavel!==false),r=window.Regras?Regras.contar(itens):{total:0,prontos:0,criticos:0};const st=n.statusProcesso||'rascunho';return`<article class="card notice-card"><div class="card-head"><div><h3>${esc(n.number)}</h3><div class="meta">${esc(companyName(n.companyId))} · ${esc(n.agency)} · Sessão ${fmt(n.opening)}${n.horaSessao?` às ${esc(String(n.horaSessao).slice(0,5))}`:''}</div></div><span class="badge ${st==='pronto'?'ok':st==='em_conferencia'?'pendente':'nao_aplicavel'}">${esc(STATUS_PROCESSO[st]||st)}</span></div><p class="notice-class">${esc(classificacaoLabel(n))}</p><p>${esc((n.object||'').slice(0,240))}${(n.object||'').length>240?'…':''}</p><div class="notice-stats"><span>${r.total?`${r.prontos}/${r.total} documentos`:'checklist não calculado'}</span>${r.criticos?`<span class="pend">${r.criticos} pendência(s)</span>`:''}<span>${(n.items||[]).length} itens</span><span>${esc(window.rotuloInteresse?rotuloInteresse(n.interesse):'')}</span></div><div class="list-row"><div class="notice-actions"><button class="primary" data-wizard="${n.id}">Abrir assistente</button>${n.filePath?`<button class="link" data-document="${esc(n.filePath)}">Abrir edital</button>`:''}<button class="link" data-go="agenda">Ver na agenda</button></div></div></article>`}).join(''):'<div class="empty">Nenhum edital cadastrado. Use o assistente para cadastrar o primeiro.</div>';renderSelects()}
function renderBalances(){$('#balance-list').innerHTML=state.balances.length?state.balances.map(b=>`<article class="card balance-card"><div class="card-head"><div><h3>${esc(companyName(b.companyId))}</h3><p>Exercício ${esc(b.year)} · ${esc(b.documentType||'Balanço anual')}</p></div><span class="badge ok">Arquivado</span></div><p>Período: ${fmt(b.periodStart)} a ${fmt(b.periodEnd)}<br>Registro/autenticação: ${fmt(b.registrationDate)}${b.registrationOffice?' · '+esc(b.registrationOffice):''}</p><div class="list-row"><small>${esc(b.notes||'Balanço e demonstrações contábeis')}</small>${b.filePath?`<button class="link" data-document="${esc(b.filePath)}">Abrir arquivo</button>`:''}</div></article>`).join(''):'<div class="empty">Nenhum balanço patrimonial arquivado.</div>'}
function renderPackages(){$('#saved-packages').innerHTML=state.packages.length?state.packages.map(p=>{const notice=state.notices.find(n=>n.id===p.noticeId),missing=(p.documents||[]).filter(d=>!d.path).length;return`<article class="card package-card"><div class="card-head"><div><h3>${esc(p.name)}</h3><p>${esc(companyName(p.companyId))} · ${esc(notice?.agency||'Órgão')}</p></div><span class="badge ${missing?'urgent':'ok'}">${missing?`${missing} pendência(s)`:'Completo'}</span></div><p>${p.documents.length} documento(s) vinculados · ${p.items.length} item(ns) na proposta</p><details><summary>Consultar documentos deste processo</summary>${p.documents.map(d=>`<div class="list-row"><span>${esc(d.title)}</span>${d.path?`<button class="link" data-document="${esc(d.path)}">Abrir</button>`:'<span class="badge missing">Pendente</span>'}</div>`).join('')}</details><button class="primary" data-download-package="${p.id}">Baixar pacote ZIP</button></article>`}).join(''):'<div class="empty">Nenhum pacote de processo criado.</div>'}
